def load() -> pd.DataFrame:
    path = 'data/biomedical/input/1-s2.0-S0092867420301070-mmc3.xlsx'
    x = pd.read_excel(path, sheet_name=None)
    parts = []
    for name, df in x.items():
        df = df.copy()
        df['__sheet'] = name
        parts.append(df)
    return pd.concat(parts, ignore_index=True)

def process(load_biomed_xlsx):
    df = load_biomed_xlsx
    mask = (df.get('__sheet') == 'D-SE-acetyl') | df.get('Description', '').astype(str).str.contains('acetyl', case=False, na=False) | df.get('Sheet', '').astype(str).str.contains('acetyl', case=False, na=False)
    sub = df[mask]
    cols = ['Gene', 'ID', 'Feature', 'REF', 'Description']
    vals = []
    for c in cols:
        if c in sub.columns:
            s = sub[c].dropna().astype(str)
            vals.extend(s.tolist())
    import re
    genes = set()
    for v in vals:
        parts = re.split(r'[;,\|/]+\s*', v)
        for p in parts:
            p = p.strip()
            if not p:
                continue
            if '-' in p:
                left = p.split('-', 1)[0]
            else:
                left = p
            left = left.split()[0]
            if re.match(r'^[A-Za-z0-9_-]+$', left):
                if left.upper() not in ('NAN', 'NA', 'README'):
                    genes.add(left)
    return pd.DataFrame({'significant_gene': sorted(genes)})

def process(load_biomed_xlsx):
